// MarshalBinary encodes Either{n} into binary form.
func (e {T}) MarshalBinary() ([]byte, error) {{
	var buf bytes.Buffer
	enc := gob.NewEncoder(&buf)

	var err error
	switch e.argId {{
{enc}	default:
		return []byte{{}}, errEither{n}InvalidArgumentId
	}}
	if err != nil {{
		return []byte{{}}, err
	}}

	return append([]byte{{byte(e.argId)}}, buf.Bytes()...), nil
}}

// UnmarshalBinary decodes Either{n} from binary form.
func (e *{T}) UnmarshalBinary(data []byte) error {{
	if len(data) == 0 {{
		return errors.New("Either{n}[{ts}].UnmarshalBinary: no data")
	}}

	dec := gob.NewDecoder(bytes.NewBuffer(data[1:]))

	switch int8(data[0]) {{
{dec}	default:
		return errEither{n}InvalidArgumentId
	}}
}}

// GobEncode implements the gob.GobEncoder interface.
func (e {T}) GobEncode() ([]byte, error) {{
	return e.MarshalBinary()
}}

// GobDecode implements the gob.GobDecoder interface.
func (e *{T}) GobDecode(data []byte) error {{
	return e.UnmarshalBinary(data)
}}
"""
    s=s.replace(f"func (e {T})",f"func (e Either{n}[{ts}])")
    f=f"either{n}.go"
